import { describe, expect, test } from 'bun:test'

import { InvalidOllamaNameError, repositoryOfOllamaName } from '../ollamaName.js'

describe('repositoryOfOllamaName — `<namespace>/<modelo>-<etiqueta>` del registro', () => {
